import{_ as a,o as t,c as e,a2 as o}from"./chunks/framework.Bg-Zxr5O.js";const u=JSON.parse('{"title":"","description":"","frontmatter":{},"headers":[],"relativePath":"manual-zh/Comma_002dSeparated-Value-Output-Options.md","filePath":"manual-zh/Comma_002dSeparated-Value-Output-Options.md","lastUpdated":1785684581000}'),s={name:"manual-zh/Comma_002dSeparated-Value-Output-Options.md"};function n(r,p,_,d,l,i){return t(),e("div",null,[...p[0]||(p[0]=[o('<h3 id="_3-8-逗号分隔值-csv-输出选项" tabindex="-1">3.8 逗号分隔值（CSV）输出选项 <a class="header-anchor" href="#_3-8-逗号分隔值-csv-输出选项" aria-label="Permalink to &quot;3.8 逗号分隔值（CSV）输出选项&quot;">​</a></h3><p>要以逗号分隔值（CSV）格式生成输出，请在 PSPP 命令行上指定 -o 文件，并可选择性地后接下表中所示的任何选项，以自定义输出格式。</p><p>-O format=csv</p><p>指定输出格式。仅当 -o 上给出的文件名不以 .csv 结尾时才需要。</p><p>-O separator=字段分隔符</p><p>设置用于分隔字段的字符。默认值：逗号（‘,’）。</p><p>-O quote=限定符</p><p>将限定符设置为用于引用包含空白、分隔符（若分隔符包含多个字符，则为其中任意字符）或引用字符本身的字段的字符。如果限定符长于一个字符，则仅使用第一个字符；如果限定符为空字符串，则字段永远不会被引用。</p><p>-O titles=布尔值</p><p>是否打印表标题（简要说明）。默认值：<code>on</code>。</p><p>-O captions=布尔值</p><p>是否打印表说明文字（更详尽的描述）。默认值：on。</p><p>所使用的 CSV 格式是对 RFC 4180 所规定格式的扩展：</p><p>表</p><p>每一表行输出在单独一行上，每一列作为一个字段输出。跨多行或多列的单元格内容仅针对其左上角的行和列输出；其余部分作为空字段输出。</p><p>标题</p><p>当表具有标题且标题功能启用时，标题输出在表正上方，作为以‘Table:’为前缀的单个字段。</p><p>说明文字</p><p>当表具有说明文字且说明文字功能启用时，说明文字输出在表正下方，作为以‘Caption:’为前缀的单个字段。</p><p>脚注</p><p>在表内，脚注标记作为括号字母输出在单元格内容之后，<em>例如</em>‘[a]’、‘[b]’……。脚注本身在表主体之后输出，作为一个以‘Footnotes:’行开头、单独的两列表格。表中的每一行表示一个脚注：第一列是标记，第二列是文本。</p><p>文本</p><p>输出中的文本作为单独一行的字段打印。TITLE 和 SUBTITLE 产生类似的输出，分别以前缀‘Title:’或‘Subtitle:’开头。</p><p>消息</p><p>错误、警告和说明以与文本相同的方式打印。</p><p>图表</p><p>图表不包含在 CSV 输出中。</p><p>连续的输出项之间以空行分隔。</p>',28)])])}const c=a(s,[["render",n]]);export{u as __pageData,c as default};
